sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color;
uniform float low;
uniform float high;
uniform float gamma;
uniform float invert;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float luma = dot(float3(unpremul(c).rgb), float3(0.2126, 0.7152, 0.0722));
    float g = clamp((pow(luma, 1.0 / max(gamma, 0.01)) - low) / max(high - low, 0.001), 0.0, 1.0);
    float k = (invert > 0.5 ? 1.0 - g : g) * float(color.a) * float(c.a);
    return half4(color.rgb * half(k), half(k));
}
